struct Item { int id; };

// Generic Template Function for Smart Pointer comparison
template <typename T>
bool ptr_less(const std::unique_ptr<T>& a,
              const std::unique_ptr<T>& b) {
    return a->id < b->id;
}

// Explicit Template Specialization for Item
template <>
bool ptr_less<Item>(const std::unique_ptr<Item>& a,
                    const std::unique_ptr<Item>& b) {
    // Custom logic: compare only the last digit
    return (a->id % 10) < (b->id % 10);
}
